 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # The object is translated toward the full-width platform until adjacent;
    # its vacated trail is filled with color 8.
    platform = next((r for r,row in enumerate(g) if len(set(row)) == 1 and row[0] != 5), None)
    if platform is None:
        return g
    bg = next((v for row in g for v in row if v not in (platform and g[platform][0], 8)), None)
    # Find non-background object cells; background is the most frequent non-platform color.
    counts = {}
    for r,row in enumerate(g):
        if r == platform: continue
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    objcolor = max((v for v in counts if v != background), key=lambda v: counts[v])
    cells = [(r,c) for r in range(h) for c in range(w) if r != platform and g[r][c] == objcolor]
    if not cells: return g
    top, bottom = min(r for r,c in cells), max(r for r,c in cells)
    # Translate rigid object to just touch the platform.
    if bottom < platform:
        delta = platform - bottom - 1
    elif top > platform:
        delta = platform - top + 1
    else:
        delta = 0
    if delta:
        for r,c in cells: g[r][c] = background
        for r,c in cells: g[r+delta][c] = objcolor
    moved = [(r+delta,c) for r,c in cells]
    # Mark the full row on the trailing side of the moved object.
    end = max(r for r,c in moved) if platform > top else min(r for r,c in moved)
    trail = end + 1 if platform < top else end - 1
    if 0 <= trail < h and trail != platform:
        g[trail] = [8]*w
    return g
